content.content:
package main

import "fmt"

func main() {
  num := 3

  if num == 1 {
    fmt.Println("One")
  } else if num == 2 {
    fmt.Println("Two")
  } else  if num == 3 {
    fmt.Println("Three")
  } else {
    fmt.Println(num)
  }
}

package main

import "fmt"

func main() {
  x := 2

  switch {
    case x>0 && x<10:
      fmt.Println("something")
    case x > 10:
      fmt.Println("something else")
  }
}

